#!/usr/bin/env python3
# Generated by Claudian.
"""Check everything JARVIS needs before you start it.

    python3 preflight.py

Catches the failures that are annoying to diagnose once the assistant is
already running and talking over your terminal.
"""

from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

G, R, Y, B, X = "\033[92m", "\033[91m", "\033[93m", "\033[94m", "\033[0m"

problems: list[str] = []
warnings: list[str] = []


def ok(msg: str) -> None:
    print(f"  {G}OK{X}    {msg}")


def bad(msg: str, fix: str) -> None:
    print(f"  {R}FAIL{X}  {msg}")
    print(f"        fix: {fix}")
    problems.append(msg)


def warn(msg: str, note: str = "") -> None:
    print(f"  {Y}WARN{X}  {msg}")
    if note:
        print(f"        {note}")
    warnings.append(msg)


def section(title: str) -> None:
    print(f"\n{B}{title}{X}")


def check_python() -> None:
    section("Python")
    v = sys.version_info
    if v < (3, 10):
        bad(f"Python {v.major}.{v.minor} is too old", "install Python 3.10+")
    else:
        ok(f"Python {v.major}.{v.minor}.{v.micro}")


def check_deps() -> None:
    section("Dependencies")
    required = {
        "groq": "pip install groq",
        "speech_recognition": "pip install SpeechRecognition",
        "pyaudio": "pip install pyaudio  (may need: brew install portaudio)",
        "dotenv": "pip install python-dotenv",
        "requests": "pip install requests",
    }
    optional = {
        "whisper": "offline speech-to-text",
        "duckduckgo_search": "web search skill",
        "psutil": "system stats skill",
        "pyjokes": "jokes skill",
        "torch": "local intent model",
        "sklearn": "local intent model",
    }
    import importlib

    missing_required = []
    for mod, fix in required.items():
        try:
            importlib.import_module(mod)
        except ImportError:
            bad(f"missing required package: {mod}", fix)
            missing_required.append(mod)
    if not missing_required:
        ok(f"all {len(required)} required packages present")

    missing_optional = []
    for mod, purpose in optional.items():
        try:
            importlib.import_module(mod)
        except ImportError:
            missing_optional.append(f"{mod} ({purpose})")
    if missing_optional:
        warn(f"{len(missing_optional)} optional packages missing",
             "; ".join(missing_optional) + "  —  pip install -r requirements.txt")
    else:
        ok(f"all {len(optional)} optional packages present")


def check_config() -> None:
    section("Configuration")
    env = Path(__file__).parent / ".env"
    if not env.exists():
        bad(".env missing", "cp .env.example .env  then add your GROQ_API_KEY")
        return
    ok(".env present")

    try:
        from config import settings
    except Exception as e:
        bad(f"config failed to load: {e}", "check .env syntax")
        return

    if settings.LLM_PROVIDER == "groq":
        if settings.GROQ_API_KEY and len(settings.GROQ_API_KEY) > 20:
            ok("GROQ_API_KEY set")
        else:
            bad("GROQ_API_KEY missing or too short",
                "get one free at console.groq.com and put it in .env")
    else:
        ok(f"LLM provider: {settings.LLM_PROVIDER}")

    # Show the actual resolved chain, not just the flag.
    try:
        from voice.audio_utils import create_recognizer
        from voice.stt_engines import build_stt
        chain = build_stt(create_recognizer())
        order = " -> ".join(e.name for e in chain.engines)
        ok(f"speech-to-text chain: {order}")
        if chain.engines and chain.engines[0].name == "whisper":
            warn("local Whisper is primary (1118ms measured)",
                 "Groq whisper-large-v3-turbo measured 229ms here — 4.9x faster "
                 "at the same accuracy. Set USE_OFFLINE_STT=false in .env to use "
                 "it. Local Whisper stays as the offline fallback either way.")
    except Exception as e:
        warn(f"could not resolve STT chain: {e}")

    if settings.USE_OFFLINE_STT:
        cache = Path.home() / ".cache" / "whisper"
        if not (cache / f"{settings.WHISPER_MODEL_SIZE}.pt").exists():
            warn("Whisper model not downloaded yet",
                 "first startup will download it (~140MB) and take a minute")

    try:
        from config.user_config import get_user_config
        c = get_user_config()
        ok(f"voice={c.get_voice()}  rate={c.get_tts_rate()}  "
           f"wake={c.get_wake_word()!r}")
        ok(f"conversation window={c.get('followup_window_sec')}s  "
           f"barge-in={c.get('bargein_mode')}")
    except Exception as e:
        warn(f"user config unreadable: {e}", "defaults will be used")


def check_microphone() -> None:
    section("Microphone")
    try:
        import speech_recognition as sr
        names = sr.Microphone.list_microphone_names()
        if not names:
            bad("no input devices found", "check System Settings > Sound > Input")
            return
        ok(f"{len(names)} input device(s); default: {names[0]!r}")
    except Exception as e:
        bad(f"cannot enumerate microphones: {e}",
            "brew install portaudio && pip install --force-reinstall pyaudio")
        return

    # Actually open it — permission problems only surface here.
    try:
        with sr.Microphone() as source:
            r = sr.Recognizer()
            r.adjust_for_ambient_noise(source, duration=0.4)
            ok(f"microphone opens; ambient energy ~{r.energy_threshold:.0f}")
            if r.energy_threshold > 4000:
                warn("noisy environment", "wake word may be less reliable")
    except Exception as e:
        bad(f"cannot open microphone: {e}",
            "System Settings > Privacy & Security > Microphone — enable Terminal")


def check_speaker() -> None:
    section("Speech output")
    try:
        from config import settings
        # Check membership in the installed-voice list rather than trying to
        # synthesise. An earlier version passed --data-format to `say`, which
        # some synthesisers reject outright — so a perfectly good voice was
        # reported as missing.
        listing = subprocess.run(
            ["say", "-v", "?"], capture_output=True, text=True, timeout=10
        )
        if listing.returncode != 0:
            warn("could not list voices", "run `say -v '?'` manually")
            return

        installed = [
            line.split()[0] for line in listing.stdout.splitlines() if line.strip()
        ]
        wanted = settings.TTS_VOICE
        if any(v.lower() == wanted.lower() for v in installed):
            ok(f"voice {wanted!r} available ({len(installed)} voices installed)")
        else:
            warn(f"voice {wanted!r} not installed",
                 "run `say -v '?'` to list; set TTS_VOICE in .env")
    except FileNotFoundError:
        bad("`say` not found", "this project requires macOS")
    except Exception as e:
        warn(f"could not verify voice: {e}")


def check_elevenlabs() -> None:
    section("Neural voice (ElevenLabs)")
    from config import settings

    if settings.TTS_ENGINE != "elevenlabs":
        ok(f"TTS engine: {settings.TTS_ENGINE} (ElevenLabs not enabled)")
        return

    if not settings.ELEVENLABS_API_KEY:
        warn("ELEVENLABS_API_KEY not set",
             "add it to .env — until then Jarvis uses the system voice")
        return

    if not settings.ELEVENLABS_VOICE_ID:
        warn("ELEVENLABS_VOICE_ID not set", "add the voice id to .env")
        return

    ok(f"voice id {settings.ELEVENLABS_VOICE_ID}  model {settings.ELEVENLABS_MODEL}")

    # Verify the key and measure real time-to-first-audio.
    try:
        import time as _t
        import requests
        from voice.speech_engines import API_URL, OUTPUT_FORMAT

        t0 = _t.perf_counter()
        resp = requests.post(
            API_URL.format(voice_id=settings.ELEVENLABS_VOICE_ID),
            params={"output_format": OUTPUT_FORMAT,
                    "optimize_streaming_latency": 3},
            json={"text": "Ready.", "model_id": settings.ELEVENLABS_MODEL},
            headers={"xi-api-key": settings.ELEVENLABS_API_KEY,
                     "Content-Type": "application/json"},
            stream=True, timeout=(6, 20),
        )
        if resp.status_code == 401:
            bad("ElevenLabs rejected the API key (401)",
                "check the key at elevenlabs.io/app/settings/api-keys")
            return
        if resp.status_code == 422:
            bad("ElevenLabs rejected the voice id or model (422)",
                f"verify voice {settings.ELEVENLABS_VOICE_ID} exists on your account")
            return
        if resp.status_code != 200:
            bad(f"ElevenLabs HTTP {resp.status_code}", resp.text[:120])
            return

        for chunk in resp.iter_content(chunk_size=4096):
            if chunk:
                ttfb = (_t.perf_counter() - t0) * 1000
                ok(f"authenticated; first audio in {ttfb:.0f}ms")
                if ttfb > 1200:
                    warn("time-to-first-audio is high",
                         "network-bound; the phrase cache will hide it for "
                         "common lines — run: python3 warm_voice_cache.py")
                break
        resp.close()
    except Exception as e:
        warn(f"could not reach ElevenLabs: {e}",
             "Jarvis will fall back to the system voice")

    try:
        from voice.speech_engines import CACHE_DIR
        n = len(list(CACHE_DIR.glob("*.pcm")))
        if n:
            ok(f"{n} phrase(s) cached (zero-latency playback)")
        else:
            warn("phrase cache empty",
                 "python3 warm_voice_cache.py  — makes common lines instant")
    except Exception:
        pass


def check_skills_and_model() -> None:
    section("Skills and model")
    try:
        from skills._registry import get_registry
        n = len(get_registry().all_skills())
        ok(f"{n} skills loaded")
    except Exception as e:
        bad(f"skill registry failed: {e}", "python3 tests/test_regressions.py")

    try:
        from ai.intent_classifier_local import get_local_classifier
        clf = get_local_classifier()
        if clf.available:
            ok(f"local intent model loaded (gate {clf.threshold})")
        else:
            warn("local intent model not loaded",
                 "optional — python3 training/train_intent_model.py --epochs 100")
    except Exception as e:
        warn(f"local model check failed: {e}")


def check_network() -> None:
    section("Network")
    import socket
    try:
        socket.create_connection(("api.groq.com", 443), timeout=5).close()
        ok("api.groq.com reachable")
    except Exception:
        from config import settings
        if settings.USE_OFFLINE_STT:
            warn("Groq unreachable", "offline STT works, but replies need Groq")
        else:
            bad("Groq unreachable", "check your internet connection")


def main() -> int:
    print("=" * 62)
    print("JARVIS PREFLIGHT".center(62))
    print("=" * 62)

    for fn in (check_python, check_deps, check_config, check_microphone,
               check_speaker, check_elevenlabs, check_skills_and_model,
               check_network):
        try:
            fn()
        except Exception as e:
            warn(f"{fn.__name__} errored: {e}")

    print("\n" + "=" * 62)
    if problems:
        print(f"  {R}{len(problems)} problem(s) must be fixed before starting{X}")
        for p in problems:
            print(f"    - {p}")
        print("=" * 62)
        return 1

    if warnings:
        print(f"  {Y}Ready, with {len(warnings)} warning(s){X}")
    else:
        print(f"  {G}All checks passed — ready to start{X}")
    print()
    print("  Start with:  python3 run.py")
    print("=" * 62)
    return 0


if __name__ == "__main__":
    sys.exit(main())
